import{d as g,C as i,o as u,c as h,a3 as a,E as t,j as n,a as d}from"./chunks/framework.Q4yG9rk_.js";const x=JSON.parse('{"title":"正易心法·前序","description":"《正易心法》前序——陈抟（希夷先生）传记。以神异出身、拒绝帝王、相人如神与传承线，为全书建立「象数真传、直追羲皇」的立场。","frontmatter":{"title":"正易心法·前序","description":"《正易心法》前序——陈抟（希夷先生）传记。以神异出身、拒绝帝王、相人如神与传承线，为全书建立「象数真传、直追羲皇」的立场。","category":"guide","aliases":["正易心法前序","陈抟传记","希夷传"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/preface.md","filePath":"yijing/zheng-yi-xin-fa/preface.md","lastUpdated":1790647676000}'),m={name:"yijing/zheng-yi-xin-fa/preface.md"},c=g({...m,setup(b){const o=[{id:"xu-01",label:"一、陈抟字号籍贯",showLabel:!0,sentences:[["陈",{text:"希夷",glossary:"xiyi"},"传陈抟，字图南，号“",{text:"扶摇子",glossary:"fuyaozi"},"”，毫州真源人。"]],note:["陈抟，字图南，号扶摇子，亳州真源人（今安徽亳州一带）。"]},{id:"xu-02",label:"二、幼年不能言",showLabel:!0,sentences:[["初生之时不能言，至四五岁戏",{text:"涡水",glossary:"guoshui"},"，水滨有一青衣",{text:"老妪乳之",glossary:"ruzhitou"},"，其后即能言，敏悟过人。"]],note:["他刚出生时不会说话，到四五岁在涡水边玩耍，水边有一位穿青衣的老妇人，把他抱在怀里哺乳，此后便能开口，聪慧过人。（「扶摇子」的号取自《庄子·逍遥游》「抟扶摇而上者九万里」，与名「抟」互文；「涡水」读 Guō。青衣老妪授能，是道教传记的常见叙事。）"]},{id:"xu-03",label:"三、经史一览无遗",showLabel:!0,sentences:[["及长，经史一览无遗。"]],note:["长大后，经史典籍一览无余，过目不忘。"]},{id:"xu-04",label:"四、所学只足记姓名",showLabel:!0,sentences:[["先生曰：“所学只足记姓名而已，吾将之游泰山，与安期、黄石辈论出世之法，安岂能与世",{text:"脂韦",glossary:"zhiwei"},{text:"汩没",glossary:"gumo"},"，出入生死、轮回人间哉。”"]],note:["陈抟说：所学不过够记个姓名罢了。我要去游泰山，同安期生、黄石公之辈谈论出世之法，怎能与世俗同流合污，在生死轮回里沉沦呢？（「脂韦」指如脂之滑、如韦之柔，喻圆滑世故；「汩没」是沉沦。安期生、黄石公都是传说中得道的方士，他以此自比，明示走方外之路。）"]},{id:"xu-05",label:"五、散尽家业携石铛",showLabel:!0,sentences:[["乃尽散其家业，惟携一",{text:"石铛",glossary:"shidang"},"而去。"]],note:["于是散尽家业，只带一口石锅离去。（石铛是三足石锅，道家煮食炼丹之器；只带这一件，是极简的象征。）"]},{id:"xu-06",label:"六、士大夫挹其清风",showLabel:!0,sentences:[["梁唐士大夫",{text:"挹其清风",glossary:"yiqingfeng"},"，得识其面，如睹",{text:"景星庆云",glossary:"jingxingqingyun"},"，然先生皆莫与交。"]],note:["梁、唐两代的士大夫仰慕他的高洁，能见他一面，如同见了景星庆云，但陈抟一概不与他们交往。（「挹清风」是仰慕高洁的雅语；「景星庆云」是祥瑞之象。）"]},{id:"xu-07",label:"七、长揖而不拜",showLabel:!0,sentences:[["明宗亲为手诏召之。先生至，长揖而不拜。明宗待之愈谨，以宫女三人赐先生。"]],note:["后唐明宗亲自下诏召见他。陈抟来了，只作长揖，不行跪拜之礼。明宗待他愈发恭敬，赐给他三名宫女。（长揖而不拜，是以平等之礼见君，暗示自己是方外之人。）"]},{id:"xu-08",label:"八、赋诗婉拒宫女",showLabel:!0,sentences:[["先生赋诗，赋曰：“云为肌体玉为腮，多谢唐王送得来。处士不兴",{text:"巫峡梦",glossary:"wu"},"，空烦云雨下阳台。”遂遁去。"]],note:["陈抟作诗婉拒：「云为肌体玉为腮，多谢唐王送得来。处士不兴巫峡梦，空烦云雨下阳台。」随即离去。（诗用宋玉《高唐赋》楚王梦神女于阳台的典故：我本不做楚王那样的梦，多谢好意。既不失礼，又婉讽明宗以美色诱隐士。）"]},{id:"xu-09",label:"九、服气辟谷二十年",showLabel:!0,sentences:[["隐武当山石岩，",{text:"服气辟谷",glossary:"biangu"},"，凡二十余年。"]],note:["他隐居在武当山的石岩中，服气辟谷，前后二十多年。（服气辟谷是道家修炼法，以呼吸吐纳代替饮食。）"]},{id:"xu-10",label:"十、移居华山",showLabel:!0,sentences:[["复移居华山，时年已七十岁矣。常闭门卧数月不起。"]],note:["后来移居华山，那时已经七十岁。他常常闭门而卧，数月不起。"]},{id:"xu-11",label:"十一、遗骸生尘",showLabel:!0,sentences:[["周世宗显德中，有樵于山麓见遗骸生尘，迫而视之，乃先生也。良久起曰：“睡酣奚为扰我。”后世宗召见，赐号“白云先生”。"]],note:["后周世宗显德年间，有樵夫在山脚下看见一具积满灰尘的「遗骸」，走近一看，正是陈抟。过了很久，他起身说：睡得正酣，为什么来打扰我？后来周世宗召见他，赐号「白云先生」。"]},{id:"xu-12",label:"十二、闻太祖登极",showLabel:!0,sentences:[["一曰乘驴游华阴，闻宋太祖登极，拍掌大笑，曰：“天下自此定矣！”"]],note:["一天，他骑驴游华阴，听说宋太祖登基，拍掌大笑说：天下从此安定了！（这一笑，是他预知天命所归的展示。）"]},{id:"xu-13",label:"十三、辞诏不赴",showLabel:!0,sentences:[["太祖召不至，再诏，辞曰：“九重仙诏，休教丹凤衔来；一片野心，已被白云留住。”太宗初年，始赴召，惟求一静室，乃赐居于建隆观为户，熟睡月余方起。辞出，赐号“",{text:"希夷",glossary:"xiyi"},"先生”。"]],note:["太祖召他，他不来；再下诏，他辞谢说：「九重仙诏，休教丹凤衔来；一片野心，已被白云留住。」（此处的「野心」指山野之志。）到太宗初年，他才赴召，只求一间静室，于是赐他在建隆观居住，熟睡了一个多月才起身。辞别出宫时，赐号「希夷先生」。"]},{id:"xu-14",label:"十四、支颐而终",showLabel:!0,sentences:[["一曰，遣门人凿石，处于张超谷。既成，先生往造而曰：“吾其死于此乎？”遂以左手支颐而终。"]],note:["一天，他派门人在张超谷凿石室。石室建成，陈抟前往察看，说：我大概就死在这里了。于是以左手托着面颊而终。"]},{id:"xu-15",label:"十五、五色云封谷口",showLabel:!0,sentences:[["数曰容色不变，肢体尚温，有五色云封谷口，弥月不散。年一百一十八岁。"]],note:["过了几天，他容色不变，肢体还是温的；有五色云封住谷口，整整一个月不散。享年一百一十八岁。"]},{id:"xu-16",label:"十六、莫道当今无天子",showLabel:!0,sentences:[["初兵纷乱太祖之时，挑太祖太宗于篮以避乱。先生遇之即吟曰：“莫道当今无天子，却将天子上担挑。”"]],note:["当初兵荒马乱、太祖还未显达时，曾把太祖、太宗挑在篮子里避难。陈抟遇见他们，便吟道：「莫道当今无天子，却将天子上担挑。」"]},{id:"xu-17",label:"十七、赵普紫微小星",showLabel:!0,sentences:[["又遇太祖太宗与赵普，游长安市，入酒肆晋坐，太祖太宗左右。先生曰：“汝",{text:"紫微垣",glossary:"ziweiyuan"},"一小星尔，轧处上次，可乎？”"]],note:["又一次，他遇见太祖、太宗与赵普，同游长安街市，进酒肆入座，太祖太宗分坐左右。陈抟对赵普说：你不过是紫微垣里的一颗小星，却挤在两个帝星的上首，可以吗？（以星象暗示赵普地位，而太祖太宗才是帝星。）"]},{id:"xu-18",label:"十八、种放之戒",showLabel:!0,sentences:[["种放初从先生，先生曰：“汝当逢明主，驰名海内，但惜天地间无完名。子名将起，必有物败之，可戒也。”放晚年竞丧清节，皆如其言。"]],note:["种放起初跟从陈抟，陈抟说：你会遇到明主，名扬海内，只可惜天地间没有完满的名声；你的名声将要起来，必定有东西败坏它，要引以为戒。种放晚年果然丧失清节，都应了他的话。"]},{id:"xu-19",label:"十九、遗药救母",showLabel:!0,sentences:[["有郭沆者，少居华阴，尝宿观下，中夜先生呼令速归，且与之俱往，一二里许，有人号呼报其母卒。先生遗以药，使急去可救。既至，灌其药，遂苏。"]],note:["有个叫郭沆的人，年少时住在华阴，曾在观下过夜。半夜陈抟叫他赶快回去，并与他同行；走了一二里，有人号哭着来报他母亲去世。陈抟给他药，让他赶快回去还可救。赶到后灌下药，母亲果然苏醒。"]},{id:"xu-20",label:"二十、华山高处是吾宫",showLabel:!0,sentences:[["华阴令王睦谓先生曰：“先生居溪岩，寝于何室？”先生且笑吟曰：“华山高处是吾宫，出即凌空跨晓风。台榭不将金锁闭，来时自有白云封。”"]],note:["华阴县令王睦问陈抟：先生住在溪岩之间，睡在什么屋里？陈抟笑着吟道：「华山高处是吾宫，出即凌空跨晓风。台榭不将金锁闭，来时自有白云封。」"]},{id:"xu-21",label:"二十一、华胥调混沌",showLabel:!0,sentences:[["一曰，有一客过访先生，适值其睡，见旁有一异人，听其息声，以黑毫记之莫辨。客怪而问之，其人曰：“此先生",{text:"华胥调混沌",glossary:"huaxu"},"也。”"]],note:["一天，有客人来访，正赶上他睡着，见旁边有一位异人，听着他的呼吸声，用黑笔记下来却看不懂。客人觉得奇怪便问，那人说：这是先生在华胥境中调和混沌啊。（华胥见《列子》，黄帝梦游华胥国，是极乐之境；此语解释陈抟入定之深，不是普通睡眠。）"]},{id:"xu-22",label:"二十二、山女赠诗",showLabel:!0,sentences:[["先生尝遇山女，山女赠之诗，诗曰：“药而不满",{text:"笥",glossary:"si"},"，又更上危巅，回指归去路，将相入翠烟。”"]],note:["陈抟曾遇见一位山中女子，女子赠他一首诗：「药而不满笥，又更上危巅，回指归去路，将相入翠烟。」（「笥」是盛物的竹器。）"]},{id:"xu-23",label:"二十三、传承线",showLabel:!0,sentences:[["太宗闻先生善相人，遣诣南山，见真宗及还。问其故。曰：“厮役皆将相也，何必见王乎？”于是建储之议遂定。先生以易数授",{text:"穆伯长",glossary:"mubochang"},"，穆授李挺之，李授",{text:"邵康节",glossary:"shaokangjie"},"。以象数学授种放，放授卢江、许坚，坚授范谔。"]],note:["太宗听说陈抟善于相人，派他去南山看真宗，他回来后，太宗问其缘故，他说：连那里的仆役都是将相之才，何必再见王呢？于是立太子之议就此定了。陈抟把易数传给穆伯长，穆传给李挺之，李传给邵康节（邵雍）；又把象数学传给种放，种放传给卢江、许坚，许坚传给范谔。"]}],l=[{id:"xiyi",term:"希夷",pinyin:"xī yí",meaning:"陈抟的赐号。《老子》「听之不闻名曰希，视之不见名曰夷」，取无声无形之道义。"},{id:"fuyaozi",term:"扶摇子",pinyin:"fú yáo zǐ",meaning:"陈抟的号。《庄子·逍遥游》「抟扶摇而上者九万里」，与其名「抟」互文。"},{id:"guoshui",term:"涡水",pinyin:"guō shuǐ",meaning:"淮河支流，流经亳州。此「涡」读 Guō，非「涡旋」之涡。"},{id:"ruzhitou",term:"老妪乳之",pinyin:"lǎo yù rǔ zhī",meaning:"老妇人把他抱在怀里哺乳。异人授能，是道教传记的标准叙事。"},{id:"zhiwei",term:"脂韦",pinyin:"zhī wéi",meaning:"脂是油脂，韦是柔皮，合指圆滑世故。"},{id:"gumo",term:"汩没",pinyin:"gǔ mò",meaning:"沉沦、埋没。与「脂韦」连用，指随波逐流。"},{id:"shidang",term:"石铛",pinyin:"shí dāng",meaning:"三足石锅，道家煮食炼丹之器，也是隐士出行的唯一携物。"},{id:"yiqingfeng",term:"挹其清风",pinyin:"yì qí qīng fēng",meaning:"挹是舀取、引申为仰慕；「挹清风」为固定雅语，表示仰慕高洁。"},{id:"jingxingqingyun",term:"景星庆云",pinyin:"jǐng xīng qìng yún",meaning:"景星是德星，庆云是五色祥云，同为祥瑞之象。"},{id:"wu",term:"巫峡梦",pinyin:"wū xiá mèng",meaning:"宋玉《高唐赋》记楚王梦神女于阳台事。陈抟以此婉拒宫女。"},{id:"biangu",term:"服气辟谷",pinyin:"fú qì bì gǔ",meaning:"道家修炼法：以呼吸吐纳代替饮食。"},{id:"huaxu",term:"华胥调混沌",pinyin:"huá xū tiáo hùn dùn",meaning:"《列子》载黄帝梦游华胥国，为极乐之境。此语形容陈抟入定之深。"},{id:"si",term:"笥",pinyin:"sì",meaning:"盛饭或衣物的竹器。山女诗中指药篓。"},{id:"ziweiyuan",term:"紫微垣",pinyin:"zǐ wēi yuán",meaning:"北极星区域，帝星所在。陈抟以之喻赵普地位。"},{id:"mubochang",term:"穆伯长",pinyin:"mù bó cháng",meaning:"穆修，字伯长，北宋文学家。易数传承第一人。"},{id:"shaokangjie",term:"邵康节",pinyin:"shào kāng jié",meaning:"邵雍，字尧夫，谥康节。先天易学集大成者。"}];return(p,e)=>{const s=i("DaoTextReading"),r=i("DaoKeywordCards");return u(),h("div",null,[e[0]||(e[0]=a("",12)),t(s,{colophon:"神异出身 · 四拒帝王 · 预知天命 · 传法两线",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法前序原文",sections:o,glossary:l}),e[1]||(e[1]=n("blockquote",null,[n("p",null,"注：本页传文依所据底本录入，异体字与个别用字（如「一曰」之「曰」、「气」等）随底本，不作统一。")],-1)),e[2]||(e[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[d("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),t(r,{items:[{term:"希夷",pinyin:["xī","yí"],meaning:"陈抟的赐号。《老子》「听之不闻名曰希，视之不见名曰夷」，取无声无形之道义。"},{term:"扶摇子",pinyin:["fú","yáo","zǐ"],meaning:"陈抟的号。《庄子·逍遥游》「抟扶摇而上者九万里」，与其名「抟」互文。"},{term:"脂韦汩没",pinyin:["zhī","wéi","gǔ","mò"],meaning:"脂是油脂、韦是柔皮，合指圆滑世故；汩没是沉沦。连用指随波逐流。"},{term:"景星庆云",pinyin:["jǐng","xīng","qìng","yún"],meaning:"景星是德星，庆云是五色祥云——汉代以来祥瑞之象的固定搭配。"},{term:"服气辟谷",pinyin:["fú","qì","bì","gǔ"],meaning:"道家修炼法，以呼吸吐纳代替饮食。"},{term:"华胥调混沌",pinyin:["huá","xū","tiáo","hùn","dùn"],meaning:"《列子》载黄帝梦游华胥国，为极乐之境。此语形容陈抟入定之深，非普通睡眠。"},{term:"紫微垣",pinyin:["zǐ","wēi","yuán"],meaning:"北极星区域，帝星所在。陈抟以之喻赵普地位，暗示太祖太宗才是帝星。"},{term:"传承两线",pinyin:["chuán","chéng"],meaning:"易数线：陈抟→穆伯长→李挺之→邵康节（先天易学）；象数线：陈抟→种放→卢江、许坚→范谔（实占应用）。"}]}),e[3]||(e[3]=a("",26))])}}});export{x as __pageData,c as default};
